using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.SGR.RecuperacionPassword;namespace GraphApi.Services.SGR.RecuperacionPassword{    public class RecuperacionPasswordService : IRecuperacionPasswordService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public RecuperacionPasswordService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadRecuperacionPassword>> GetRecuperacionPasswords(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM sgr.RecuperacionPassword (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadRecuperacionPassword>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetRecuperacionPasswordsDynamic(            int? recuperacionPasswordID,            int? usuarioID,            string? token,            DateTime? fechaGeneracion,            DateTime? fechaExpiracion,            bool? usado,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "RecuperacionPasswordID, UsuarioID, Token, FechaGeneracion, FechaExpiracion, Usado, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM sgr.RecuperacionPassword (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (recuperacionPasswordID.HasValue)            {                vSql.Append(" AND RecuperacionPasswordID = @RecuperacionPasswordID");                vParameters.Add("RecuperacionPasswordID",recuperacionPasswordID);            }            if (!string.IsNullOrWhiteSpace(token))            {                vSql.Append(" AND Token LIKE @Token");                vParameters.Add("Token",$"%{token}%");            }            if (usado.HasValue)            {                vSql.Append(" AND Usado = @Usado");                vParameters.Add("Usado", usado.Value);            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadRecuperacionPassword> CreateRecuperacionPassword(clCreateRecuperacionPassword objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO sgr.RecuperacionPassword                (UsuarioID, Token, FechaGeneracion, FechaExpiracion, Usado, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@UsuarioID, @Token, @FechaGeneracion, @FechaExpiracion, @Usado, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.UsuarioID,                objInput.Token,                objInput.FechaGeneracion,                objInput.FechaExpiracion,                objInput.Usado,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT RecuperacionPasswordID, UsuarioID, Token, FechaGeneracion, FechaExpiracion, Usado, bEliminado                FROM sgr.RecuperacionPassword (NOLOCK)                WHERE RecuperacionPasswordID = @RecuperacionPasswordID;";            var vReadParams = new { RecuperacionPasswordID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadRecuperacionPassword>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el RecuperacionPassword con ID {vNewId}.");            return vCreated;        }        public async Task<clReadRecuperacionPassword?> UpdateRecuperacionPassword(clUpdateRecuperacionPassword objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("RecuperacionPasswordID", objInput.RecuperacionPasswordID);            if (objInput.UsuarioID != null)            {                vSets.Add("UsuarioID = @UsuarioID");                vParameters.Add("UsuarioID", objInput.UsuarioID);            }            if (objInput.Token is not null)            {                vSets.Add("Token = @Token");                vParameters.Add("Token", objInput.Token);            }            if (objInput.FechaGeneracion != null)            {                vSets.Add("FechaGeneracion = @FechaGeneracion");                vParameters.Add("FechaGeneracion", objInput.FechaGeneracion);            }            if (objInput.FechaExpiracion != null)            {                vSets.Add("FechaExpiracion = @FechaExpiracion");                vParameters.Add("FechaExpiracion", objInput.FechaExpiracion);            }            if (objInput.Usado != null)            {                vSets.Add("Usado = @Usado");                vParameters.Add("Usado", objInput.Usado);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE sgr.RecuperacionPassword                SET {vSetClause}                WHERE RecuperacionPasswordID = @RecuperacionPasswordID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT RecuperacionPasswordID, UsuarioID, Token, FechaGeneracion, FechaExpiracion, Usado, bEliminado                FROM sgr.RecuperacionPassword (NOLOCK)                WHERE RecuperacionPasswordID = @RecuperacionPasswordID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadRecuperacionPassword>(sSelect, new {  objInput.RecuperacionPasswordID });        }        public async Task<bool> DeleteRecuperacionPassword(int nRecuperacionPasswordID)        {            const string sSql = @"                DELETE FROM sgr.RecuperacionPassword                WHERE RecuperacionPasswordID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nRecuperacionPasswordID });            return vAffected > 0;        }    }}